
import { Link } from "@/lib/navigation";
import { useTranslations } from "@/i18n/useTranslations";
import { FetchInstance } from "@/api/FetchInstance";
import { toast } from "react-toastify";
import { useState } from "react";
import { EyeInvisibleOutlined, EyeTwoTone } from "@ant-design/icons";
import { useParams } from "react-router-dom";
import RecaptchaProvider from "@/components/auth/RecaptchaProvider";
import { useRecaptcha } from "@/hooks/useRecaptcha";
import { isRecaptchaEnabled } from "@/lib/recaptcha";

const initialForm = {
  phone_or_email: "",
  password: "",
};

type LoginFormProps = {
  getRecaptchaToken?: () => Promise<string | null>;
};

function LoginForm({
  getRecaptchaToken,
  recaptchaReady = true,
}: LoginFormProps & { recaptchaReady?: boolean }) {
  const t = useTranslations("login");
  const locale = useParams().locale || "uz";
  const [form, setForm] = useState(initialForm);
  const [error, setError] = useState<{ status?: string }>({});
  const [loading, setLoading] = useState(false);
  const [passwordVisible, setPasswordVisible] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const togglePasswordVisibility = () => {
    setPasswordVisible(!passwordVisible);
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    if (getRecaptchaToken) {
      const token = await getRecaptchaToken();
      if (!token) {
        setError({
          status:
            "Captcha tekshiruvi muvaffaqiyatsiz. Google Console: v3 site key, domenlar (localhost, innoweek.uz). Sahifani yangilang.",
        });
        return;
      }
    }

    setLoading(true);
    setError({});

    try {
      const res = (await FetchInstance("/api/v1.0/user/login", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(form),
      })) as { success?: boolean; data?: { access_token: string } };

      if (res?.success && res.data?.access_token) {
        localStorage.setItem("token", res.data.access_token);
        toast.success(t("login_success"));
        window.location.pathname = `/${locale}/profile`;
      } else {
        setError({ status: t("login_failed") });
      }
    } catch (err) {
      console.error(err);
      setError({ status: t("login_error") });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="mt-10 pt-20 pb-15 flex items-center justify-center !w-full sm:!w-11/12 md:w-10/12 lg:!w-1/2 mx-auto dark:bg-[radial-gradient(circle,#0085d4_0%,#031119_40%)] dark:bg-[#151a28] min-h-[65vh]">
      <div className="bg-white dark:!bg-transparent rounded-2xl p-8 max-w-11/12 w-full shadow-2xl shadow-[#10374d74] border dark:!border-gray-700 relative ">
        <div className="absolute -top-8 left-1/2 -translate-x-1/2 w-15 h-15 rounded-full bg-[#0085d4] flex items-center justify-center shadow-lg border-4 border-white dark:border-[#151a28]">
          <svg width="30" height="30" fill="#fff" viewBox="0 0 24 24">
            <path d="M12 2C6.477 2 2 6.477 2 12c0 5.523 4.477 10 10 10s10-4.477 10-10c0-5.523-4.477-10-10-10zm0 18a8 8 0 1 1 0-16 8 8 0 0 1 0 16zm-1-13h2v6h-2zm0 8h2v2h-2z" />
          </svg>
        </div>
        <h2 className="!text-2xl !mt-2 font-extrabold !mb-4 !text-[#0085d4] text-center tracking-wide">
          {t("login_title")}
        </h2>

        <form onSubmit={handleSubmit} className="flex flex-col gap-3">
          <div>
            <input
              type="text"
              name="phone_or_email"
              placeholder={t("phone_or_email")}
              className="border-2 border-[#0085d4] rounded-lg px-3 py-2 w-full"
              value={form.phone_or_email}
              onChange={handleChange}
              required
            />
            <label
              htmlFor="phone_or_email"
              className="!text-gray-400 m-1 text-sm"
            >
              {t("phone_format")}
            </label>
          </div>
          <div className="relative">
            <input
              type={passwordVisible ? "text" : "password"}
              name="password"
              placeholder={t("password")}
              className="border-2 border-[#0085d4] rounded-lg px-3 py-2 w-full"
              value={form.password}
              onChange={handleChange}
              required
            />
            <span
              className="absolute right-3 top-1/2 transform -translate-y-1/2 cursor-pointer"
              onClick={togglePasswordVisibility}
            >
              {!passwordVisible ? (
                <EyeTwoTone twoToneColor="#0085d4" />
              ) : (
                <EyeInvisibleOutlined />
              )}
            </span>
          </div>

          {error.status && (
            <span className="text-red-500 text-xs">{error.status}</span>
          )}

          <button
            type="submit"
            disabled={loading || (Boolean(getRecaptchaToken) && !recaptchaReady)}
            className={`w-full font-bold !rounded-full p-2 flex items-center justify-center gap-2 shadow-lg transition-all duration-200 text-lg tracking-wide mx-auto ${
              loading
                ? "bg-gray-400 text-gray-200 cursor-not-allowed"
                : "bg-[#0085d4] hover:bg-[#e3a127] text-white"
            }`}
          >
            {loading ? (
              <>
                <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                {t("logging_in")}
              </>
            ) : (
              t("login_title")
            )}
          </button>
        </form>

        <p className="text-center mt-4">
          {t("no_account")}
          <Link href="/register" className="text-[#0085d4] ml-1">
            {t("register")}
          </Link>
        </p>
        <p className="text-center mt-2">
          <Link
            href="/forgot-password"
            className="text-[#e3a127] hover:underline font-semibold"
          >
            {t("forgot_password")}
          </Link>
        </p>
        {getRecaptchaToken && (
          <p className="text-center text-[11px] text-gray-500 dark:text-gray-400 mt-4 leading-relaxed px-2">
            Google reCAPTCHA v3: checkbox yo‘q; himoya «Kirish» bosilganda fon
            rejimida ishlaydi. O‘ng pastdagi reCAPTCHA belgisi paydo bo‘lishi
            mumkin.
          </p>
        )}
      </div>
    </div>
  );
}

function LoginWithRecaptcha() {
  const { getToken, ready } = useRecaptcha("login");
  return (
    <LoginForm
      recaptchaReady={ready}
      getRecaptchaToken={getToken}
    />
  );
}

export default function Login() {
  if (!isRecaptchaEnabled()) {
    return <LoginForm />;
  }
  return (
    <RecaptchaProvider>
      <LoginWithRecaptcha />
    </RecaptchaProvider>
  );
}
